import { customType, timestamp, uuid } from "drizzle-orm/pg-core";

/** Case-insensitive text (Postgres `citext` extension). Used for emails. */
export const citext = customType<{ data: string }>({
  dataType() {
    return "citext";
  },
});

/** Primary key: a random UUID generated by the database. */
export const id = () => uuid("id").primaryKey().defaultRandom();

/** created_at / updated_at. Drizzle refreshes updated_at on every update. */
export const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

/** Soft delete. Rows are never removed; set this instead. */
export const archivedAt = () =>
  timestamp("archived_at", { withTimezone: true });
